-- #######################################################################################
-- HYPRLAND CONFIG (Lua, Hyprland 0.55+) - MODULAR STRUCTURE
-- #######################################################################################
--
-- Migrated from the old hyprlang hyprland.conf + conf/*.conf (kept for reference).
-- Each module lives in ~/.config/hypr/conf/<name>.lua and is loaded with require().
--
-- - monitors.lua (top level) : Monitor configuration, generated by nwg-displays
-- - conf/programs.lua        : Default applications (returned as a table)
-- - conf/autostart.lua       : Startup programs
-- - conf/environment.lua     : Environment variables
-- - conf/appearance.lua      : Look and feel (borders, gaps, shadows, blur)
-- - conf/animations.lua      : Animation curves and settings
-- - conf/layouts.lua         : Window layout settings (dwindle, master)
-- - conf/input.lua           : Input device settings (keyboard, mouse, touchpad)
-- - conf/keybinds.lua        : Keyboard shortcuts and bindings
-- - conf/windowrules.lua     : Window rules and workspace rules
-- - colors.lua (top level)   : Catppuccin palette, generated by matugen
--
-- API: https://wiki.hypr.land/configuring/  (stubs: /usr/share/hypr/stubs/hl.meta.lua)
-- Check for errors without reloading: Hyprland --verify-config
-- #######################################################################################

-- Generated, untracked files: load if present so a fresh install still boots.
local function optional(mod)
    local ok, res = pcall(require, mod)
    if not ok then print("hyprland.lua: optional module '" .. mod .. "' not loaded: " .. tostring(res)) end
    return ok, res
end

-- monitors.lua is written by nwg-displays; fall back to auto-config without it
if not optional("monitors") then
    hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
end

require("conf.autostart")
require("conf.environment")
require("conf.appearance")
require("conf.animations")
require("conf.layouts")
require("conf.input")
require("conf.keybinds")
require("conf.windowrules")

-- matugen palette (table with helpers; not applied to anything yet, same as the old setup)
optional("colors")
